
'use strict';

function icon(name){const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',folder:'<path d="M3 7V5h7l2 3h9v12H3Z"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',file:'<path d="M5 3h10l4 4v14H5ZM14 3v5h5M8 12h8M8 16h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15c3 1 3 3 3 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h3M14 15h3"/>',check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 12 3 3 5-6"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8.5 8.5 0 1 0 10 10Z"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4"/>'};return `<span class="navicon" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[name]||paths.file}</svg></span>`}
function toggleNav(){if(matchMedia('(max-width:800px)').matches){document.getElementById('sidebar').classList.toggle('open')}else{document.body.classList.toggle('nav-collapsed')}}
function toggleTheme(){document.body.classList.toggle('night');try{localStorage.setItem('mro-siviki-theme',document.body.classList.contains('night')?'night':'day')}catch{}}
try{document.body.classList.toggle('night',localStorage.getItem('mro-siviki-theme')==='night')}catch{}
function overviewCharts(){const total=db.projects.length;const counts=Object.keys(types).map(w=>db.projects.filter(p=>p.w===w).length);const max=Math.max(1,...counts);const exam=db.projects.filter(p=>p.status==='Dalam pemeriksaan').length;const clarify=db.projects.filter(p=>p.status==='Perlu klarifikasi').length;const draft=db.projects.filter(p=>p.status==='Draft internal').length;const pct=n=>total?n/total*100:0;return `<div class="overview-analytics"><section class="panel"><div class="chart-heading"><h2>Project per jenis verifikasi</h2><small>Seluruh data simulasi</small></div><div class="workflow-chart"><div class="dash-bars" role="img" aria-label="${counts.map((n,i)=>`W${i+1}: ${n} Project`).join(', ')}">${counts.map((n,i)=>`<div class="dash-bar-item"><span class="cube ${['cube-blue','cube-yellow','cube-navy','cube-teal'][i]}" style="height:${n?Math.max(12,n/max*82):0}px"><strong>${n}</strong></span><span class="bar-label">W${i+1}</span></div>`).join('')}</div><div class="chart-legend">${Object.entries(types).map(([w,t],i)=>`<span><i class="legend-dot" style="background:${['#2b8dc8','#e4a129','#4a6c89','#36b4bf'][i]}"></i>${t}</span>`).join('')}</div></div></section><section class="panel"><div class="chart-heading"><h2>Status pemeriksaan Project</h2><small>Seluruh Project</small></div><div class="status-chart"><div class="donut" style="--exam:${pct(exam)}%;--clarify:${pct(exam+clarify)}%;--draft:${pct(exam+clarify+draft)}%" role="img" aria-label="${total} Project; ${exam} dalam pemeriksaan, ${clarify} perlu klarifikasi, ${draft} draft internal, ${total-exam-clarify-draft} lainnya"><div class="donut-label">${total}<small>Total Project</small></div></div><div class="status-legend">${[['Dalam pemeriksaan',exam,'#3fc4e6'],['Perlu klarifikasi',clarify,'#e4a129'],['Draft internal',draft,'#244bb7'],['Lainnya',total-exam-clarify-draft,'#cdd8ec']].map(([label,n,c])=>`<div><i class="legend-dot" style="background:${c}"></i>${label}<b>${n}</b></div>`).join('')}</div></div></section></div>`}

const VERSION='MRO-Siviki-v1.3 / 23-11-2026';
const types={W1:'Verifikasi Awal',W2:'Verifikasi Perubahan',W3:'Pemeriksaan Realisasi',W4:'Verifikasi Barang Sisa'};
const outputs={W1:'SKVI',W2:'SKVI Perubahan',W3:'Laporan Hasil Pemeriksaan',W4:'SKVBS (jika berlaku)'};
const roles=['Petugas Operasional','Verifikator','Penanggung Jawab Operasional','System Administrator'];
const seed={projects:[{id:'MRO-DEMO-001',name:'PT Aero Nusantara',w:'W1',status:'Dalam pemeriksaan',owner:'Dimas Pratama',due:'2026-11-25',location:'Hanggar Tangerang',ref:'SIM-PMH-001',source:'Pencatatan manual · dokumen simulasi',result:'Belum disusun',official:'Belum dikonfirmasi',progress:43},{id:'MRO-DEMO-002',name:'PT Cakrawala Teknik Aviasi',w:'W2',status:'Perlu klarifikasi',owner:'Rani Wibowo',due:'2026-11-26',location:'Workshop Bekasi',ref:'SIM-SKVI-2026-014',source:'Pencatatan manual · dokumen simulasi',result:'Draft simulasi',official:'Belum dikonfirmasi',progress:60},{id:'MRO-DEMO-003',name:'PT Dirgantara Servis Mandiri',w:'W3',status:'Dalam pemeriksaan',owner:'Dimas Pratama',due:'2026-11-27',location:'Hanggar Surabaya',ref:'SIM-SKVI-2026-009',source:'Pencatatan manual · dokumen simulasi',result:'Draft simulasi',official:'Tidak disimulasikan',progress:50},{id:'MRO-DEMO-004',name:'PT Aero Nusantara',w:'W4',status:'Perlu klarifikasi',owner:'Rani Wibowo',due:'2026-11-30',location:'Gudang Tangerang',ref:'SIM-SKVI-2026-006',source:'Pencatatan manual · dokumen simulasi',result:'Belum disusun',official:'Tidak disimulasikan',progress:25}],schedules:[{id:1,project:'MRO-DEMO-001',activity:'Pemeriksaan lapangan',date:'2026-11-23',start:'09:00',end:'11:00',person:'Dimas Pratama',method:'Offline',location:'Hanggar Tangerang'},{id:2,project:'MRO-DEMO-002',activity:'Klarifikasi perubahan',date:'2026-11-24',start:'10:00',end:'11:00',person:'Rani Wibowo',method:'Online',location:'Ruang diskusi simulasi'},{id:3,project:'MRO-DEMO-003',activity:'Rekonsiliasi realisasi',date:'2026-11-25',start:'13:00',end:'15:00',person:'Dimas Pratama',method:'Online',location:'Ruang diskusi simulasi'}],findings:[{id:1,project:'MRO-DEMO-001',title:'Spesifikasi hydraulic pump belum konsisten',item:'Hydraulic pump · PN HP-204',note:'Part number pada rencana impor berbeda dengan lembar spesifikasi. Mohon penjelasan dan bukti yang diperbarui.',status:'Terbuka'},{id:2,project:'MRO-DEMO-002',title:'Kapasitas pendukung kenaikan jumlah belum tersedia',item:'Matriks perubahan jumlah',note:'Tambahkan referensi kapasitas fasilitas untuk mendukung perubahan 40 menjadi 60 unit.',status:'Terbuka'},{id:3,project:'MRO-DEMO-003',title:'Selisih 2 unit perlu ditelusuri',item:'Seal kit · PN SK-017',note:'Rekonsiliasi 100 unit impor, 70 digunakan dan 28 persediaan menyisakan selisih 2 unit. Selisih bukan kesimpulan pelanggaran.',status:'Terbuka'},{id:4,project:'MRO-DEMO-004',title:'Bukti kondisi barang perlu dilengkapi',item:'Bearing assembly · PN BA-320',note:'Foto label dan referensi dokumen pabean belum terhubung.',status:'Terbuka'}],checks:{},drafts:{},categories:{},activity:[]};
let storageOK=true;function getStored(key,fallback){try{const val=localStorage.getItem(key);return val?JSON.parse(val):fallback}catch(e){storageOK=false;return fallback}}let db=getStored('mro-siviki-demo-v1',structuredClone(seed));let feedback=getStored('mro-siviki-feedback-v1',[]);let role=getStored('mro-siviki-role-v1','Verifikator');let view='mine',scheduleView='calendar',selectedItem=0,group='Rencana kebutuhan impor',wizardStep=1,wizard={},route=[];
function save(){try{localStorage.setItem('mro-siviki-demo-v1',JSON.stringify(db))}catch(e){storageOK=false;toast('Penyimpanan browser tidak tersedia. Perubahan hanya bertahan selama halaman ini terbuka.')}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function date(s){return new Date(s+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}function btn(t,fn,cls=''){return `<button type="button" class="${cls}" onclick="${fn}">${t}</button>`}function badge(t,cls=''){return `<span class="badge ${cls}">${esc(t)}</span>`}function project(){return db.projects.find(p=>p.id===route[1])||db.projects[0]}function go(path){location.hash=path}function log(p,t){db.activity.unshift({project:p,time:new Date().toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}),text:t});save()}function toast(t){document.getElementById('live').innerHTML=`<div class="toast">${esc(t)}</div>`;setTimeout(()=>document.getElementById('live').innerHTML='',4500)}
function dialog(title,body){document.getElementById('modal').innerHTML=`<div class="dialoghead"><h2>${title}</h2><button class="close" aria-label="Tutup dialog" onclick="closeModal()">×</button></div><div class="dialogbody">${body}</div>`;document.getElementById('modal').showModal()}function closeModal(){document.getElementById('modal').close()}function download(name,data,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function navlink(path,label){return `<a class="${(location.hash.slice(1)||'home')===path?'active':''}" href="#${path}">${label}</a>`}function side(){return `<aside class="sidebar" id="sidebar"><div class="brand"><i class="brandmark"></i><div>MRO<small>Aviation verification platform</small></div><button class="close-nav" aria-label="Tutup navigasi" onclick="toggleNav()">×</button></div><nav>${navlink('home',icon('grid')+'Beranda')}<details open><summary>${icon("folder")}Project</summary>${navlink('schedule',icon('calendar')+'Jadwal dan Penugasan')}${Object.entries(types).map(([w,t])=>navlink('list/'+w,`${icon('check')}${t} <span style="margin-left:auto;font-size:12px">${w}</span>`)).join('')}</details><details ${route[0]==='master'?'open':''}><summary>${icon("database")}Master</summary>${['Perusahaan MRO','Fasilitas & Lokasi','Referensi Barang & HS Code','Jenis Verifikasi','Kategori Dokumen'].map((n,i)=>navlink('master/'+i,n)).join('')}</details><details ${route[0]==='documents'?'open':''}><summary>${icon("file")}Dokumen & Laporan</summary>${['SKVI & Perubahan','Pemeriksaan Realisasi','SKVBS','Laporan Operasional'].map((n,i)=>navlink('documents/'+i,n)).join('')}</details><details ${route[0]==='admin'?'open':''}><summary>${icon("users")}Administrasi</summary>${['Pengguna','Role & Hak Akses','Audit Aktivitas','Pengaturan Sistem'].map((n,i)=>navlink('admin/'+i,n)).join('')}</details></nav></aside>`}
function head(title,desc,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}function shell(content){return `<div class="shell">${side()}<div><header class="topbar"><div class="toplinks"><button class="mobilemenu" aria-label="Buka navigasi" onclick="toggleNav()">☰</button><span class="reviewlabel small muted">${esc(({home:"Beranda",schedule:"Project",list:"Project",project:"Project",register:"Registrasi Project",master:"Master",documents:"Dokumen & Laporan",admin:"Administrasi",feedback:"Feedback client",guide:"Panduan"})[route[0]]||"MRO")} <span style="color:#b6cbd5">/</span> <b style="color:var(--navy)">MRO</b></span></div><div class="toplinks"><a href="#public" class="small">Website publik</a><button class="top-icon" aria-label="Ganti tema" onclick="toggleTheme()">${icon("moon")}</button><button class="top-icon" aria-label="Lihat temuan terbuka" onclick="go('project/MRO-DEMO-001/findings')">${icon("bell")}</button><span class="top-divider"></span><select aria-label="Simulasi peran" onchange="setRole(this.value)">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><span class="avatar" title="Akun simulasi">DP</span><div class="user-meta"><b>Dimas Pratama</b><br><small>Akun demonstrasi</small></div></div></header><main class="main" id="main">${!storageOK?'<div class="note warning">Penyimpanan browser tidak tersedia. Ekspor feedback sebelum menutup halaman.</div>':''}${content}</main></div></div>`}function setRole(v){role=v;try{localStorage.setItem('mro-siviki-role-v1',JSON.stringify(v))}catch{}toast('Simulasi tampilan peran: '+v+'. Hak akses belum diterapkan; menunggu SOP.');render()}
function tableProjects(list){return `<div class="tablewrap"><table><thead><tr><th>Project / perusahaan</th><th>Jenis</th><th>Status Project</th><th>Verifikator</th><th>Target operasional</th><th></th></tr></thead><tbody>${list.map(p=>`<tr class="clickrow" data-search="${esc((p.name+' '+p.id+' '+p.w+' '+p.status).toLowerCase())}"><td><a class="projectlink" href="#project/${p.id}/summary">${esc(p.name)}</a><small>${p.id} · simulasi</small></td><td><span class="workflow">${p.w}</span></td><td>${badge(p.status,p.status.includes('klarifikasi')?'amber':'')}<small>${RV.progress(p)}% selesai diperiksa</small></td><td>${esc(p.owner)}</td><td>${date(p.due)}</td><td><a href="#project/${p.id}/verification">Periksa</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada Project. Gunakan Registrasi Project untuk membuat contoh baru.</td></tr>'}</tbody></table><div id="no-results" class="empty hide">Tidak ada Project yang cocok dengan pencarian.</div></div>`}function filterRows(q){let n=0;document.querySelectorAll('[data-search]').forEach(e=>{let match=e.dataset.search.includes(q.toLowerCase());e.classList.toggle('hide',!match);if(match)n++});document.getElementById('no-results')?.classList.toggle('hide',n>0)}
function home(){let mine=db.projects.filter(p=>p.owner==='Dimas Pratama');let list=view==='mine'?mine:db.projects;let f=db.findings.filter(f=>f.status!=='Selesai').length;return head('Beranda','Selamat datang, Dimas. Fokus pada pekerjaan yang membutuhkan tindakan.',btn('Registrasi Project',"startRegistration()",'primary'))+`<div class="segments">${btn('Pekerjaan Saya',"view='mine';render()",view==='mine'?'selected':'')}${btn('Monitoring Project',"view='all';render()",view==='all'?'selected':'')}</div><div class="priority"><span class="symbol">◎</span><div><h2>Lengkapi klarifikasi spesifikasi barang</h2><p>PT Aero Nusantara · W1 · Hydraulic pump HP-204 · Target 25 Nov 2026</p></div>${btn('Lanjutkan verifikasi',"go('project/MRO-DEMO-001/verification')",'primary')}</div><div class="stats"><div class="stat"><em>W1–W4</em><span>Project aktif</span><b>${db.projects.length}</b></div><div class="stat"><span>Pekerjaan saya</span><b>${mine.length}</b></div><div class="stat"><span>Temuan terbuka</span><b>${f}</b></div><div class="stat"><span>Jadwal kegiatan</span><b>${db.schedules.length}</b></div></div>${overviewCharts()}<div class="columns"><section class="panel flush"><div style="padding:20px 20px 0"><div class="panelhead"><h2>${view==='mine'?'Pekerjaan saya':'Monitoring seluruh Project'}</h2>${badge(list.length+' Project','gray')}</div><div class="toolbar"><input aria-label="Cari Project" placeholder="Cari perusahaan atau nomor Project…" oninput="filterRows(this.value)"></div></div>${tableProjects(list)}<div style="padding:14px 20px" class="small muted">Target operasional adalah simulasi, bukan perhitungan SLA regulasi.</div></section><aside><section class="panel"><div class="panelhead"><h2>Agenda terdekat</h2><a class="small" href="#schedule">Lihat jadwal</a></div>${db.schedules.slice(0,3).map(s=>`<div class="agenda"><time>${date(s.date)} · ${s.start}</time><p><b>${esc(s.activity)}</b></p><small>${esc(db.projects.find(p=>p.id===s.project)?.name)}<br>${esc(s.location)}</small></div>`).join('')}</section><section class="panel"><h3>Yang perlu divalidasi</h3><p class="small muted">Apakah menu, urutan pemeriksaan, dan tindakan berikutnya sudah mendukung pekerjaan tim?</p><a class="small" href="#guide">Buka skenario review</a></section></aside></div>`}
function listPage(){let w=route[1] in types?route[1]:'W1';return head(types[w],`${w} · ${outputs[w]} · Data seluruh perusahaan di bawah adalah simulasi.`,btn('Jadwal dan Penugasan',"go('schedule')"))+`<section class="panel"><div class="toolbar"><input aria-label="Cari Project" placeholder="Cari perusahaan atau nomor Project…" oninput="filterRows(this.value)"><select aria-label="Filter status" onchange="filterRows(this.value)"><option value="">Semua status</option><option>Dalam pemeriksaan</option><option>Perlu klarifikasi</option><option>Draft internal</option></select></div>${tableProjects(db.projects.filter(p=>p.w===w))}</section><div class="note">Project baru diregistrasikan melalui <a href="#schedule">Jadwal dan Penugasan</a>. Registrasi tidak otomatis membuat jadwal atau dokumen hasil.</div>`}
function schedule(){return head('Jadwal dan Penugasan','Kelola Project, penugasan personel, dan kegiatan secara terpisah.',btn('Registrasi Project','startRegistration()')+btn('Tambah Jadwal','openSchedule()','primary'))+`<div class="stats"><div class="stat"><span>Project terdaftar</span><b>${db.projects.length}</b></div><div class="stat"><span>Kegiatan terjadwal</span><b>${db.schedules.length}</b></div><div class="stat"><span>Tanpa jadwal</span><b>${db.projects.filter(p=>!db.schedules.some(s=>s.project===p.id)).length}</b></div><div class="stat"><span>Personel contoh</span><b>2</b></div></div><div class="panel"><div class="panelhead"><h2>November 2026</h2><div class="segments">${btn('Kalender',"scheduleView='calendar';render()",scheduleView==='calendar'?'selected':'')}${btn('Daftar',"scheduleView='list';render()",scheduleView==='list'?'selected':'')}</div></div><div class="small muted">Periode demo November 2026. Tambah kegiatan melalui tombol Tambah Jadwal.</div>${scheduleView==='calendar'?calendar():scheduleTable()}</div><section class="panel"><div class="panelhead"><h2>Penugasan Project</h2>${badge('Independen dari jadwal','gray')}</div>${tableAssignment()}</section><div class="note">Mengubah jadwal tidak mengubah tanggal permohonan, pemicu regulasi, atau identitas Project. Aturan SLA dan kewenangan penugasan masih perlu validasi client.</div>`}
function calendar(){let days='';for(let i=0;i<35;i++){let n=i+1;let valid=n>=1&&n<=30;let ds='2026-11-'+String(n).padStart(2,'0');days+=`<div class="day ${n===22?'today':''} ${!valid?'out':''}"><span>${valid?n:n===0?31:n-30}</span>${valid?db.schedules.filter(s=>s.date===ds).map(s=>`<button onclick="openSchedule(${s.id})">${s.start} ${esc(s.activity)}</button>`).join(''):''}</div>`}return `<div class="tablewrap" style="margin-top:20px"><div class="calendar">${['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map(d=>`<div class="calhead">${d}</div>`).join('')}${days}</div></div>`}
function scheduleTable(){return `<div class="tablewrap"><table><thead><tr><th>Kegiatan</th><th>Project</th><th>Tanggal & waktu</th><th>Personel</th><th></th></tr></thead><tbody>${[...db.schedules].sort((a,b)=>a.date.localeCompare(b.date)).map(s=>`<tr><td>${esc(s.activity)}<small>${esc(s.method)} · ${esc(s.location)}</small></td><td><a href="#project/${s.project}/summary">${s.project}</a></td><td>${date(s.date)}<small>${s.start}–${s.end}</small></td><td>${esc(s.person)}</td><td>${btn('Ubah jadwal',`openSchedule(${s.id})`,'textbutton')}</td></tr>`).join('')}</tbody></table></div>`}
function tableAssignment(){return `<div class="tablewrap"><table><thead><tr><th>Project</th><th>Jenis</th><th>Penanggung jawab pemeriksaan</th><th></th></tr></thead><tbody>${db.projects.map(p=>`<tr><td>${esc(p.name)}<small>${p.id}</small></td><td>${p.w}</td><td>${esc(p.owner)}</td><td>${btn('Ubah penugasan',`assign('${p.id}')`,'textbutton')}</td></tr>`).join('')}</tbody></table></div>`}
function assign(id){let p=db.projects.find(p=>p.id===id);dialog('Penugasan Project',`<form onsubmit="saveAssignment(event,'${id}')"><p class="note">${p.id} · ${esc(p.name)}<br>Simulasi; kewenangan penugasan belum disahkan.</p><label for="aperson">Verifikator</label><select id="aperson"><option ${p.owner==='Dimas Pratama'?'selected':''}>Dimas Pratama</option><option ${p.owner==='Rani Wibowo'?'selected':''}>Rani Wibowo</option></select><label for="areason">Alasan perubahan</label><textarea id="areason" required></textarea><div class="footeractions"><button class="primary">Simpan penugasan simulasi</button></div></form>`)}function saveAssignment(e,id){e.preventDefault();let p=db.projects.find(p=>p.id===id);let old=p.owner;p.owner=document.getElementById('aperson').value;log(id,`Penugasan ${old} menjadi ${p.owner}. Alasan: ${document.getElementById('areason').value}. Jadwal lama tetap tercatat.`);closeModal();render();toast('Penugasan diperbarui. Riwayat tersimpan; jadwal terkait dapat ditinjau terpisah.')}
function openSchedule(id){let s=db.schedules.find(s=>s.id===id)||{project:route[0]==='project'?project().id:db.projects[0].id,date:'2026-11-26',start:'09:00',end:'10:00',activity:'Pemeriksaan dokumen',person:'Dimas Pratama',method:'Online',location:''};dialog(id?'Ubah Jadwal':'Tambah Jadwal',`<form onsubmit="saveSchedule(event,${id||0})"><p class="note">Pilih Project yang sudah terdaftar. Satu Project dapat memiliki beberapa jadwal.</p><label for="sproject">Project</label><select id="sproject" onchange="document.getElementById('sperson').value=db.projects.find(p=>p.id===this.value).owner">${db.projects.map(p=>`<option value="${p.id}" ${p.id===s.project?'selected':''}>${p.id} · ${esc(p.name)} (${p.w})</option>`).join('')}</select><div class="formgrid"><div><label for="sactivity">Kegiatan</label><input id="sactivity" required value="${esc(s.activity)}"></div><div><label for="sperson">Personel pada kegiatan</label><select id="sperson">${['Dimas Pratama','Rani Wibowo'].map(n=>`<option ${n===s.person?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="sdate">Tanggal (periode demo)</label><input id="sdate" type="date" min="2026-11-01" max="2026-11-30" value="${s.date}" required></div><div><label for="smethod">Metode</label><select id="smethod"><option ${s.method==='Online'?'selected':''}>Online</option><option ${s.method==='Offline'?'selected':''}>Offline</option></select></div><div><label for="sstart">Mulai</label><input id="sstart" type="time" value="${s.start}" required></div><div><label for="send">Selesai</label><input id="send" type="time" value="${s.end}" required></div><div class="wide"><label for="slocation">Lokasi / ruang diskusi</label><input id="slocation" value="${esc(s.location)}" required></div><div class="wide"><label for="sletter">Referensi Surat Tugas (opsional)</label><input id="sletter" value="${esc(s.letter||'')}" placeholder="Referensi simulasi jika tersedia"></div>${id?'<div class="wide"><label for="sreason">Alasan penjadwalan ulang</label><input id="sreason" required></div>':''}</div><p id="serror" class="error" role="alert"></p><div class="footeractions"><button type="button" onclick="closeModal()">Batal</button><button class="primary">Simpan jadwal simulasi</button></div></form>`)}
function saveSchedule(e,id){e.preventDefault();let v=n=>document.getElementById('s'+n).value;let err='';if(v('end')<=v('start'))err='Waktu selesai harus setelah waktu mulai.';if(db.schedules.some(s=>s.id!==id&&s.date===v('date')&&s.person===v('person')&&s.start<v('end')&&s.end>v('start')))err='Personel memiliki jadwal yang bertabrakan. Pilih waktu atau personel lain.';if(db.projects.find(p=>p.id===v('project')).owner!==v('person'))err='Personel belum ditugaskan ke Project ini. Ubah penugasan Project terlebih dahulu.';if(err){document.getElementById('serror').textContent=err;return}let old=db.schedules.find(s=>s.id===id);let item={id:id||Date.now(),project:v('project'),activity:v('activity'),date:v('date'),start:v('start'),end:v('end'),person:v('person'),method:v('method'),location:v('location'),letter:v('letter')};if(id)db.schedules[db.schedules.findIndex(s=>s.id===id)]=item;else db.schedules.push(item);log(item.project,id?`Jadwal ${old.date} ${old.start}–${old.end} diubah menjadi ${item.date} ${item.start}–${item.end}. Alasan: ${v('reason')}. Pemicu regulasi tidak berubah.`:`Jadwal ${item.activity} ditambahkan ${item.date} ${item.start}.`);closeModal();render();toast('Jadwal simulasi disimpan di browser ini.')}
function startRegistration(){wizardStep=1;wizard={w:'W1',name:'',ref:'',date:'2026-11-22',location:'',source:'Dokumen simulasi client',doc:'',description:''};go('register');if(route[0]==='register')render()}
function registerPage(){if(!wizard.w)wizard={w:'W1',name:'',ref:'',date:'2026-11-22',location:'',source:'Dokumen simulasi client',doc:'',description:''};return head('Registrasi Project','Membuat identitas pekerjaan internal; jadwal dan penugasan dapat ditambahkan sesudahnya.')+`<div class="steps">${['Informasi Project','Referensi & Dokumen','Review & Simpan'].map((s,i)=>`<div class="step ${wizardStep===i+1?'active':''}">${i+1}. ${s}</div>`).join('')}</div><form class="panel" style="max-width:980px" onsubmit="wizardNext(event)">${wizardStep===1?`<fieldset><legend>Informasi Project</legend><div class="formgrid"><div><label for="rw">Jenis verifikasi</label><select id="rw" onchange="wizard.w=this.value">${Object.entries(types).map(([w,t])=>`<option value="${w}" ${wizard.w===w?'selected':''}>${w} · ${t}</option>`).join('')}</select></div><div><label for="rname">Perusahaan MRO (simulasi)</label><input id="rname" required value="${esc(wizard.name)}" placeholder="Contoh: PT MRO Demo Baru" oninput="wizard.name=this.value"></div><div><label for="rref">Referensi permohonan manual</label><input id="rref" required value="${esc(wizard.ref)}" placeholder="SIM-PMH-005" oninput="wizard.ref=this.value"></div><div><label for="rdate">Tanggal permohonan pada sumber</label><input id="rdate" required type="date" value="${wizard.date}" oninput="wizard.date=this.value"></div><div><label for="rlocation">Lokasi fasilitas</label><input id="rlocation" required value="${esc(wizard.location)}" oninput="wizard.location=this.value"></div><div><label for="rsource">Sumber data</label><input id="rsource" required value="${esc(wizard.source)}" oninput="wizard.source=this.value"></div><div class="wide"><label for="rdesc">Deskripsi pekerjaan</label><textarea id="rdesc" oninput="wizard.description=this.value">${esc(wizard.description)}</textarea></div></div></fieldset>`:wizardStep===2?`<fieldset><legend>Referensi & Dokumen · ${wizard.w}</legend><p class="note">${wizard.w==='W1'?'Catat referensi persyaratan awal dan Surat Penetapan simulasi.':'Catat referensi SKVI asal dan dokumen pendukung. Tidak mengambil data dari SIINas.'}</p><label for="rdoc">${wizard.w==='W1'?'Referensi persyaratan awal (boleh menyusul sebagai draft)':'Referensi SKVI asal (wajib untuk contoh alur ini)'}</label><input id="rdoc" ${wizard.w!=='W1'?'required':''} value="${esc(wizard.doc)}" placeholder="SIM-SKVI-2026-… / SIM-PENETAPAN-…" oninput="wizard.doc=this.value">${wizard.w==='W4'?'<p class="small muted">Kategori kondisi dan bukti barang akan ditinjau pada tab Verifikasi; SKVBS tidak dibuat otomatis.</p>':''}<label for="rattachment">Pilih berkas contoh (opsional; hanya nama berkas dicatat)</label><input id="rattachment" type="file" onchange="wizard.file=this.files[0]?.name||''"><p class="small muted">Berkas tidak diunggah atau dibaca. Hindari memakai dokumen asli pada demo.</p>${wizard.file?`<p>${esc(wizard.file)}</p>`:''}</fieldset>`:`<fieldset><legend>Review Project internal</legend><div class="keyvalues"><div><small>Perusahaan</small><b>${esc(wizard.name)}</b></div><div><small>Jenis</small>${wizard.w} · ${types[wizard.w]}</div><div><small>Referensi permohonan</small>${esc(wizard.ref)}</div><div><small>Tanggal sumber</small>${date(wizard.date)}</div><div><small>Referensi dokumen</small>${esc(wizard.doc||'Belum tersedia')}</div><div><small>Sumber</small>${esc(wizard.source)}</div></div>${db.projects.some(p=>p.ref.toLowerCase()===wizard.ref.toLowerCase())?'<div class="note warning">Potensi duplikasi referensi ditemukan. Periksa Project yang sudah ada sebelum membuat pekerjaan baru.</div><label><input id="rduplicate" type="checkbox" required>Saya sudah meninjau potensi duplikasi untuk simulasi ini.</label>':''}<div class="note">Akan disimpan sebagai <b>Draft internal</b>, belum ditugaskan dan belum memiliki jadwal. Kelengkapan tidak berarti sudah sesuai.</div><label><input type="checkbox" required>Saya memahami ini data simulasi dan bukan registrasi resmi.</label></fieldset>`}<div class="footeractions">${wizardStep>1?btn('Kembali',"wizardStep--;render()") :btn('Batal',"go('schedule')")}<button class="primary">${wizardStep===3?'Simpan Project simulasi':'Lanjutkan'}</button></div></form>`}
function wizardNext(e){e.preventDefault();if(wizardStep<3){wizardStep++;render();return}let id='MRO-DEMO-'+String(db.projects.length+1).padStart(3,'0');db.projects.push({id,name:wizard.name,w:wizard.w,status:'Draft internal',owner:'Belum ditugaskan',due:'2026-11-30',location:wizard.location,ref:wizard.w==='W1'?wizard.ref:wizard.doc,requestRef:wizard.ref,fresh:true,source:wizard.source,result:'Belum disusun',official:'Belum dikonfirmasi',progress:0,document:wizard.doc,requestDate:wizard.date,description:wizard.description,file:wizard.file||''});log(id,'Project diregistrasi manual sebagai draft. Referensi dan tanggal sumber dicatat; belum dijadwalkan.');go('project/'+id+'/summary');toast('Project simulasi dibuat. Penugasan dan jadwal dapat ditambahkan terpisah.')}
function detail(){return RV.mount(project(),route[2]||'summary')}
function summary(p){let fs=db.findings.filter(f=>f.project===p.id&&f.status!=='Selesai').length;let ss=db.schedules.filter(s=>s.project===p.id);return `<div class="stats"><div class="stat"><span>Jumlah step verifikasi</span><b>${p.w==='W1'?7:3}</b></div><div class="stat"><span>Selesai diperiksa</span><b>${RV.progress(p)}%</b><div class="progress"><i style="width:${RV.progress(p)}%"></i></div></div><div class="stat"><span>Temuan terbuka</span><b>${fs}</b></div><div class="stat"><span>Jadwal terkait</span><b>${ss.length}</b></div></div><div class="twocol"><section class="panel"><h2>Identitas & sumber data</h2><div class="keyvalues"><div><small>Referensi ${p.w==='W1'?'permohonan':'SKVI asal'}</small>${esc(p.ref)}</div>${p.requestRef?`<div><small>Referensi permohonan manual</small>${esc(p.requestRef)}</div>`:''}<div><small>Nomor internal</small>${p.id}</div><div><small>Lokasi</small>${esc(p.location)}</div><div><small>Penanggung jawab pemeriksaan</small>${esc(p.owner)}</div><div><small>Sumber data</small>${esc(p.source)}</div><div><small>Tanggal pencatatan demo</small>22 Nov 2026</div><div><small>Target operasional (simulasi)</small>${date(p.due)}</div><div><small>Pemicu waktu regulasi</small>Belum dikonfirmasi dari sumber resmi</div></div><div class="note small">Nomor Project berbeda dari nomor permohonan SIINas. Integrasi SIINas ditunda; seluruh input di prototype bersifat manual.</div>${btn('Ubah penugasan',`assign('${p.id}')`)}</section><section class="panel"><div class="panelhead"><h2>Agenda & pekerjaan</h2>${btn('Tambah Jadwal','openSchedule()','textbutton')}</div>${ss.length?ss.map(s=>`<div class="agenda"><time>${date(s.date)} · ${s.start}–${s.end}</time><p>${esc(s.activity)}</p><small>${esc(s.person)} · ${esc(s.location)}</small></div>`).join(''):'<p class="muted">Belum ada jadwal. Project dapat ditugaskan sebelum kegiatan dijadwalkan.</p>'}<h3 style="margin-top:18px">Buka verifikasi</h3><p class="small muted">${{W1:'Persyaratan, rencana impor, fasilitas dan pemeriksaan lapangan.',W2:'Bandingkan data sebelumnya dengan perubahan yang diajukan.',W3:'Rekonsiliasi impor, penggunaan dan persediaan pada tingkat item.',W4:'Tinjau kategori kondisi, identitas barang dan bukti terkait.'}[p.w]}</p>${btn('Mulai verifikasi',`go('project/${p.id}/verification')`,'primary')}</section></div>`}
const groups=['Identitas perusahaan','Dokumen persyaratan','Rencana kebutuhan impor','Rencana kegiatan MRO','Kapasitas fasilitas','Subkontrak (jika ada)','Pemeriksaan lapangan'];
const items=[{name:'Hydraulic pump',pn:'HP-204',hs:'SIM-HS-001',quantity:40,unit:'unit',evidence:'Lembar spesifikasi HP-204 · v2',note:'Part number pada dokumen pendukung perlu klarifikasi.'},{name:'Seal kit',pn:'SK-017',hs:'SIM-HS-002',quantity:100,unit:'set',evidence:'Rencana kebutuhan impor · v1',note:'Satuan set perlu konsisten pada semua dokumen.'},{name:'Bearing assembly',pn:'BA-320',hs:'SIM-HS-003',quantity:25,unit:'unit',evidence:'Katalog komponen BA-320 · v1',note:'Periksa identitas dan kapasitas pendukung.'}];
function inspection(p){return `${p.fresh?'<div class="note warning">Project baru: data teknis di area ini adalah contoh demonstrasi yang dapat dipakai menguji interaksi, bukan data yang dimasukkan saat registrasi.</div>':''}<div class="panelhead"><div><h2>${{W1:'Persyaratan & fasilitas MRO',W2:'Matriks perubahan',W3:'Rekonsiliasi realisasi',W4:'Kondisi & klasifikasi barang sisa'}[p.w]}</h2><span class="small muted">Pengelompokan dan penilaian adalah usulan desain; checklist resmi menunggu client.</span></div>${badge(p.w)}</div>${p.w==='W1'?w1(p):p.w==='W2'?w2(p):p.w==='W3'?w3(p):w4(p)}`}
function w1(p){return inspectionTimeline(p)}
function itemPanel(p,it,i){return `<div style="margin-top:20px"><div class="panelhead"><h3>${it.name}</h3>${badge('Data tersedia','gray')}</div><div class="keyvalues"><div><small>Part number</small>${it.pn}</div><div><small>Referensi HS simulasi</small>${it.hs}</div><div><small>Jumlah rencana</small>${it.quantity} ${it.unit}</div><div><small>Bukti terkait</small>${it.evidence}</div></div><p class="note">${it.note} Kode HS di demo bukan klasifikasi tarif yang sah.</p>${assessment(p,'item-'+i)}<div class="actions">${btn('Lihat bukti',`previewEvidence('${it.evidence}','${p.id}')`)}${btn('Catat temuan',`newFinding('${p.id}','${it.name} · ${it.pn}')`)}</div></div>`}
function assessment(p,key){let c=db.checks[p.id+'|'+key]||{};const recorded=Boolean(c.value),groupIndex=groups.indexOf(key);if(!recorded&&!p.fresh&&p.w==='W1'&&groupIndex>=0&&groupIndex<3)c={value:groupIndex<2?'Sesuai':'Perlu klarifikasi'};return `<label>Penilaian verifikator (simulasi)<select aria-label="Penilaian ${esc(key)}" onchange="setAssessment('${p.id}','${key}',this.value)">${['Belum dinilai','Sesuai','Perlu klarifikasi','Tidak sesuai','Tidak relevan'].map(v=>`<option ${c.value===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="small muted">${c.value?(recorded?'Penilaian tersimpan lokal: ':'Penilaian contoh: ')+esc(c.value):'Pilih hasil setelah meninjau bukti.'}</p>`}function setAssessment(id,key,val){db.checks[id+'|'+key]={value:val};log(id,'Penilaian '+key+': '+val+' (simulasi).');render();refreshInspectionGroup();toast('Penilaian simulasi disimpan. Status resmi tidak berubah.')}
function w2(p){return `<div class="note">Referensi asal: <b>${esc(p.ref)}</b> · Versi data v1 → usulan v2. Data historis dipertahankan. Contoh konflik versi: tidak ada perubahan paralel pada data demo.</div><div class="panel"><label for="change-category">Kategori perubahan yang ditinjau</label><select id="change-category" onchange="db.categories['${p.id}-change']=this.value;save();render()">${['Jumlah rencana impor','Identitas perusahaan','Penambahan jenis barang'].map(v=>`<option ${db.categories[p.id+'-change']===v?'selected':''}>${v}</option>`).join('')}</select><div class="tablewrap" style="margin-top:20px"><table><thead><tr><th>Objek</th><th>Sebelumnya · v1</th><th>Diajukan · v2</th><th>Perubahan</th></tr></thead><tbody>${(db.categories[p.id+'-change']==='Identitas perusahaan'?[['Alamat workshop','Blok A-1','Blok A-3','Alamat'],['Nama perusahaan',p.name,p.name,'Tetap']]:db.categories[p.id+'-change']==='Penambahan jenis barang'?[['Seal kit','100 set','100 set','Tetap'],['Filter assembly','Tidak tercantum','20 unit','Item baru']]:[['Hydraulic pump','40 unit','60 unit','+20 unit'],['Seal kit','100 set','100 set','Tetap']]).map(r=>`<tr>${r.map((c,i)=>`<td>${i===3?badge(c,c==='Tetap'?'gray':'amber'):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="note warning">Periksa ${db.categories[p.id+'-change']==='Identitas perusahaan'?'bukti perubahan identitas':db.categories[p.id+'-change']==='Penambahan jenis barang'?'spesifikasi, kebutuhan dan bukti pendukung item baru':'bukti kapasitas untuk perubahan jumlah'}. Perubahan tidak otomatis diterima. Masa berlaku dan kewenangan perlu konfirmasi dari sumber resmi.</div>${assessment(p,'matriks-perubahan')}<div class="actions">${btn('Bukti usulan perubahan',`previewEvidence('Usulan perubahan · v2','${p.id}')`)}${btn('Catat temuan',`newFinding('${p.id}','Matriks perubahan')`)}</div></div>`}
function w3(p){return `<div class="note">Referensi ${esc(p.ref)}. Selisih ditampilkan untuk penelusuran; tidak otomatis menjadi pelanggaran. Seluruh angka di bawah simulasi.</div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Barang</th><th>Impor</th><th>Digunakan</th><th>Persediaan</th><th>Selisih</th><th></th></tr></thead><tbody>${[['Hydraulic pump','40','30','10','0'],['Seal kit','100','70','28','2'],['Bearing assembly','25','20','5','0']].map((r,i)=>`<tr><td>${r[0]}<small>${items[i].pn} · ${items[i].unit}</small></td>${r.slice(1).map((v,j)=>`<td>${j===3?badge(v,v!=='0'?'amber':'green'):v}</td>`).join('')}<td>${btn('Telusuri bukti',`selectedItem=${i};render()`,'textbutton')}</td></tr>`).join('')}</tbody></table></div><div class="note ${selectedItem===1?'warning':''}"><b>Item terpilih: ${items[selectedItem].name}</b><br>${selectedItem===1?'100 impor − 70 digunakan − 28 persediaan = selisih 2 set. Perlu klarifikasi sumber dan mutasi barang.':'Jumlah tercatat konsisten pada contoh ini. Penilaian substansi tetap perlu bukti.'}</div><div class="twocol"><div><h3>Bukti rekonsiliasi</h3><p class="small muted">Realisasi impor · Catatan penggunaan · Daftar stok · Subkontrak bila relevan.</p>${btn('Lihat bukti item',`previewEvidence('Rekonsiliasi ${items[selectedItem].pn}','${p.id}')`)}</div><div>${assessment(p,'rekonsiliasi-'+selectedItem)}${btn('Catat temuan',`newFinding('${p.id}','${items[selectedItem].name}')`)}</div></div></div>`}
function w4(p){let cat=db.categories[p.id]||'Tidak sesuai spesifikasi';return `<div class="splitwork"><section class="panel"><h3>Barang yang ditinjau</h3><div class="keyvalues"><div><small>Barang / Part number</small>Bearing assembly · BA-320</div><div><small>Jumlah / satuan</small>5 unit (simulasi)</div><div><small>Referensi pabean</small>SIM-PIB-2026-031</div><div><small>Referensi SKVI</small>${esc(p.ref)}</div></div><label for="condition">Kategori kondisi</label><select id="condition" onchange="db.categories['${p.id}']=this.value;save();render()">${['Tidak sesuai spesifikasi','Rusak / cacat','Persediaan tidak digunakan ≥18 bulan'].map(v=>`<option ${cat===v?'selected':''}>${esc(v)}</option>`).join('')}</select><div class="note ${cat.includes('18')?'warning':''}">${cat.includes('18')?'Kategori persediaan tidak digunakan memerlukan penelaahan khusus. Prototype tidak menyimpulkan kewajiban atau membuat SKVBS otomatis.':'Tinjau '+(cat==='Rusak / cacat'?'foto kerusakan, penilaian kondisi dan identitas barang.':'spesifikasi diajukan, barang aktual dan bukti perbedaannya.')+' SKVBS hanya kandidat hasil jika berlaku.'}</div>${assessment(p,'kondisi-barang')}<label for="condition-note">Catatan kondisi simulasi</label><textarea id="condition-note" onchange="db.drafts['${p.id}-condition']=this.value;save()" placeholder="Contoh: label identitas belum terbaca pada foto…">${esc(db.drafts[p.id+'-condition']||'')}</textarea><div class="actions" style="margin-top:14px">${btn('Catat temuan',`newFinding('${p.id}','Bearing assembly · BA-320')`)}${btn('Lihat bukti kondisi',`previewEvidence('Foto kondisi dan label BA-320','${p.id}')`)}</div></section><aside class="panel"><h3>Bukti yang perlu ditinjau</h3>${['Identitas dan label barang','Foto kondisi aktual','Referensi dokumen pabean','Spesifikasi / riwayat persediaan'].map((t,i)=>`<div class="checkgroup"><div><b class="small">${t}</b><p>${i<2?'Contoh tersedia':'Perlu dilengkapi'}</p></div></div>`).join('')}<p class="small muted" style="margin-top:20px">Klasifikasi dan perlakuan dokumen harus dikonfirmasi client. Kewajiban pabean tidak diputuskan oleh prototype.</p></aside></div>`}
function evidence(p){let list=[['Dokumen persyaratan','Referensi perusahaan · v1'],['Rencana kebutuhan impor','Tabel barang · v1'],['Lembar spesifikasi','HP-204 · v2'],['Foto fasilitas & kondisi barang','Kunjungan contoh · v1'],['Berita Acara & Surat Tugas','Contoh placeholder · v1']];return `<section class="panel"><div class="panelhead"><h2>Dokumen & Bukti</h2>${btn('Lampirkan contoh',`attachEvidence('${p.id}')`,'primary')}</div><p class="small muted">Berkas pada demo adalah representasi. Ketersediaan bukti tidak menandakan kesesuaian.</p><div class="tablewrap"><table><thead><tr><th>Dokumen / bukti</th><th>Versi & konteks</th><th>Ketersediaan</th><th>Penilaian</th><th></th></tr></thead><tbody>${list.map((d,i)=>`<tr><td><span class="fileicon">DOC</span> &nbsp;${d[0]}</td><td>${d[1]}<small>Sumber: manual simulasi</small></td><td>${badge(i===4?'Placeholder':'Contoh tersedia','gray')}</td><td>${badge(i===2?'Perlu klarifikasi':'Belum dinilai',i===2?'amber':'gray')}</td><td>${btn('Preview',`previewEvidence('${d[0]}','${p.id}')`,'textbutton')}</td></tr>`).join('')}${(db.attachments||[]).filter(a=>a.project===p.id).map((a,i)=>`<tr><td>${esc(a.name)}</td><td>Nama berkas saja<small>${esc(a.note)}</small></td><td>${badge('Metadata lokal','gray')}</td><td>Belum dinilai</td><td>${btn('Lihat metadata',`previewAttachment('${p.id}',${i})`,'textbutton')}</td></tr>`).join('')}</tbody></table></div></section>`}
function previewAttachment(id,index){let a=(db.attachments||[]).filter(a=>a.project===id)[index];previewEvidence('Metadata lampiran: '+a.name,id)}
function previewEvidence(title,id){dialog('Preview bukti simulasi',`<div class="note">${esc(title)} · ${esc(id)}<br>Representasi bukti untuk review interaksi; tidak menampilkan dokumen asli.</div><div class="document"><div class="stamp">PROTOTYPE / BUKAN DOKUMEN RESMI</div><h2 style="margin-top:24px">${esc(title)}</h2><p>Objek: komponen / fasilitas MRO simulasi</p><p>Referensi: SIM-EVID-2026 · Versi contoh v1</p><p>Bukti dihubungkan pada objek pemeriksaan agar verifikator dapat menelusuri sumber penilaian.</p><hr style="border:0;border-top:1px solid var(--border)"><p class="muted">Konten ini hanya menunjukkan posisi preview dan metadata. Tidak dapat digunakan sebagai bukti verifikasi.</p></div><div class="footeractions">${btn('Tutup','closeModal()')}</div>`)}
function attachEvidence(id){dialog('Lampirkan contoh bukti',`<form onsubmit="saveAttachment(event,'${id}')"><p class="note">Hanya nama berkas dan catatan dicatat lokal. Isi berkas tidak diunggah atau disimpan.</p><label for="efile">Berkas contoh</label><input type="file" id="efile" required><label for="enote">Konteks bukti</label><input id="enote" required placeholder="Contoh: spesifikasi Hydraulic pump"><div class="footeractions"><button class="primary">Catat metadata contoh</button></div></form>`)}function saveAttachment(e,id){e.preventDefault();let f=document.getElementById('efile').files[0];db.attachments=db.attachments||[];db.attachments.push({project:id,name:f.name,note:document.getElementById('enote').value});log(id,'Metadata bukti dicatat: '+f.name);closeModal();render();toast('Metadata bukti tersimpan lokal; isi berkas tidak diunggah.')}
function findings(p){let f=db.findings.filter(f=>f.project===p.id);return `<div class="panelhead"><h2>Temuan & klarifikasi</h2>${btn('Tambah temuan',`newFinding('${p.id}','Verifikasi Project')`,'primary')}</div>${f.length?f.map(f=>`<article class="finding" style="background:white"><div class="panelhead">${badge(f.status,f.status==='Selesai'?'green':'amber')}<span class="small muted">TM-${f.id} · ${esc(f.item)}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.note)}</p>${f.response?`<div class="note"><b>Tindak lanjut:</b> ${esc(f.response)}</div>`:''}<div class="actions">${btn('Catat tindak lanjut',`respondFinding(${f.id})`)}${btn('Lihat bukti',`previewEvidence('Bukti temuan TM-${f.id}','${p.id}')`)}</div></article>`).join(''):'<section class="panel empty">Belum ada temuan. Penilaian dan catatan dapat ditambahkan dari tab Verifikasi.</section>'}<p class="small muted">Tindak lanjut di sini adalah catatan internal simulasi. Tidak mengirim klarifikasi kepada perusahaan atau SIINas.</p>`}
function newFinding(id,item){dialog('Catat temuan simulasi',`<form onsubmit="saveFinding(event,'${id}')"><label for="fitem">Objek terkait</label><input id="fitem" value="${esc(item)}" required><label for="ftitle">Judul temuan</label><input id="ftitle" required><label for="fnote">Penjelasan & bukti yang diperlukan</label><textarea id="fnote" required></textarea><div class="footeractions"><button type="button" onclick="closeModal()">Batal</button><button class="primary">Simpan temuan</button></div></form>`)}function saveFinding(e,id){e.preventDefault();db.findings.push({id:Date.now(),project:id,item:document.getElementById('fitem').value,title:document.getElementById('ftitle').value,note:document.getElementById('fnote').value,status:'Terbuka'});log(id,'Temuan baru dicatat (simulasi).');closeModal();go('project/'+id+'/findings');render();toast('Temuan disimpan di browser ini.')}
function respondFinding(id){let f=db.findings.find(f=>f.id===id);dialog('Tindak lanjut temuan',`<form onsubmit="saveResponse(event,${id})"><p class="note">${esc(f.title)}</p><label for="fresponse">Catatan tindak lanjut</label><textarea id="fresponse" required>${esc(f.response||'')}</textarea><label for="fstatus">Status simulasi</label><select id="fstatus">${['Terbuka','Menunggu klarifikasi','Selesai'].map(v=>`<option ${v===f.status?'selected':''}>${v}</option>`).join('')}</select><div class="footeractions"><button class="primary">Simpan tindak lanjut</button></div></form>`)}function saveResponse(e,id){e.preventDefault();let f=db.findings.find(f=>f.id===id);f.response=document.getElementById('fresponse').value;f.status=document.getElementById('fstatus').value;log(f.project,'Temuan diperbarui menjadi '+f.status+'; '+f.response);closeModal();render();toast('Tindak lanjut internal disimpan. Tidak ada pesan yang dikirim.')}
function result(p){let d=db.drafts[p.id]||{note:'',review:false,prepared:false};let conditional=p.w==='W4'&&(db.categories[p.id]||'').includes('18');return `<div class="note">${p.w==='W3'?'Hasil W3 adalah laporan pemeriksaan realisasi, bukan SKVI.':conditional?'Kategori persediaan belum memastikan kebutuhan SKVBS. Preview ditampilkan sebagai catatan penelaahan.':'Draft '+outputs[p.w]+' disusun dari konteks hasil pemeriksaan.'} Template, kesiapan, reviewer dan kewenangan masih provisional.</div><div class="twocol"><section class="panel"><h2>Penyusunan hasil</h2><div class="keyvalues"><div><small>Perusahaan</small>${esc(p.name)}</div><div><small>Workflow / sumber snapshot</small>${p.w} · Demo v1</div><div><small>Referensi</small>${esc(p.ref)}</div><div><small>Dokumen</small>${conditional?'Catatan penelaahan':outputs[p.w]}</div></div><label for="resultnote">Kesimpulan / catatan draft simulasi</label><textarea id="resultnote" oninput="saveDraftNote('${p.id}',this.value)" placeholder="Tulis catatan hasil untuk dipreview bersama client…">${esc(d.note)}</textarea><div class="note small">Nomor dokumen: belum diberikan.<br>Tanda tangan: tidak disimulasikan.<br>Status resmi: ${esc(p.official)}.</div><div class="actions">${btn('Simpan draft simulasi',`prepareDraft('${p.id}')`,'primary')}${btn('Preview draft',`previewResult('${p.id}')`)}</div><hr style="border:0;border-top:1px solid var(--border);margin:24px 0"><label><input type="checkbox" id="reviewcheck" ${d.review?'checked':''} onchange="setReviewCheck('${p.id}',this.checked)">Saya sudah meninjau draft untuk diskusi client.</label><p class="small muted">Ini konfirmasi demo, bukan readiness checklist resmi.</p>${btn('Simulasikan review internal',`simulateReview('${p.id}')`)}${d.reviewStatus?`<div class="note">${esc(d.reviewStatus)} · tidak menerbitkan dokumen.</div>`:''}</section><section><div class="panelhead"><h3>Preview dokumen</h3>${badge('Draft · belum resmi','amber')}</div>${documentPreview(p,d,conditional)}</section></div>`}
function documentPreview(p,d,conditional){return `<div class="document"><div class="stamp">PROTOTYPE / BUKAN DOKUMEN RESMI</div><h2 style="margin-top:28px">${conditional?'Catatan penelaahan kategori barang sisa':outputs[p.w]}</h2><p><b>${esc(p.name)}</b><br>Project ${p.id} · ${p.w}<br>Referensi ${esc(p.ref)}</p><p id="draftpreview">${esc(d.note||'Belum ada kesimpulan simulasi. Isi catatan pada panel penyusunan hasil.')}</p><p class="small muted">Seluruh isi dan tata letak ini untuk memvalidasi pengalaman pengguna. Bukan template resmi, keputusan verifikasi atau pernyataan kewenangan.</p><p class="small">Nomor resmi: tidak tersedia<br>Tanda tangan / cap: tidak tersedia</p></div>`}
function saveDraftNote(id,v){db.drafts[id]={...(db.drafts[id]||{}),note:v};save();let el=document.getElementById('draftpreview');if(el)el.textContent=v||'Belum ada kesimpulan simulasi.'}function setReviewCheck(id,v){db.drafts[id]={...(db.drafts[id]||{}),review:v};save()}function prepareDraft(id){let p=db.projects.find(p=>p.id===id);let d=db.drafts[id]||{};if(!d.note?.trim()){toast('Isi catatan draft terlebih dahulu.');return}d.prepared=true;db.drafts[id]=d;p.result='Draft simulasi';log(id,'Draft hasil simulasi disimpan; status resmi tidak berubah.');render();toast('Draft simulasi disimpan. Bukan dokumen resmi.')}
function previewResult(id){let p=db.projects.find(p=>p.id===id),d=db.drafts[id]||{};dialog('Preview draft hasil',documentPreview(p,d,p.w==='W4'&&(db.categories[p.id]||'').includes('18'))+`<div class="footeractions">${btn('Unduh catatan draft',`downloadDraft('${id}')`)}${btn('Tutup','closeModal()')}</div>`)}function downloadDraft(id){let p=db.projects.find(p=>p.id===id);download(id+'-DRAFT-SIMULASI.txt',`PROTOTYPE / BUKAN DOKUMEN RESMI\n${outputs[p.w]} — kandidat desain, bukan template resmi\n${p.name} / ${p.id}\nReferensi: ${p.ref}\n\n${db.drafts[id]?.note||'Belum ada catatan.'}\n\nTidak bernomor resmi. Tidak ditandatangani. Tidak diterbitkan. Status resmi tidak berubah.`)}
function simulateReview(id){let p=db.projects.find(p=>p.id===id),d=db.drafts[id]||{};if(!d.prepared||!d.review){toast('Simpan draft dan centang peninjauan untuk mencoba simulasi review.');return}dialog('Simulasi review internal',`<p class="note">Tidak mengirim permohonan, tidak menerbitkan ${outputs[p.w]} dan tidak mencatat Tanda Sah. Role serta alur review harus divalidasi client.</p><p>Hasil simulasi dipilih untuk memperlihatkan alur revisi atau draft yang menunggu review.</p><label for="reviewoutcome">Skenario</label><select id="reviewoutcome"><option>Menunggu review internal (simulasi)</option><option>Perlu revisi (simulasi)</option></select><div class="footeractions">${btn('Jalankan simulasi',`finishReview('${id}')`,'primary')}</div>`)}function finishReview(id){let p=db.projects.find(p=>p.id===id),v=document.getElementById('reviewoutcome').value;db.drafts[id].reviewStatus=v;p.result=v;log(id,v+'; status Project dan status resmi tetap terpisah.');closeModal();render();toast('Skenario review diperbarui. Tidak ada dokumen yang diterbitkan.')}
function showHistory(id){let list=db.activity.filter(a=>a.project===id);dialog('Riwayat aktivitas simulasi',`<p class="note">${id} · Jejak perubahan hanya tersimpan di browser ini.</p>${list.length?list.map(a=>`<div class="agenda"><time>${esc(a.time)} WIB</time><p>${esc(a.text)}</p></div>`).join(''):'<div class="agenda"><time>22 Nov 2026</time><p>Data awal simulasi dimuat. Belum ada perubahan pengguna.</p></div>'}`)}
function masterPage(){let i=Number(route[1]||0),names=['Perusahaan MRO','Fasilitas & Lokasi','Referensi Barang & HS Code','Jenis Verifikasi','Kategori Dokumen'];let headers,rows;if(i===0){headers=['Perusahaan','Referensi identitas','Fasilitas'];rows=[['PT Aero Nusantara','SIM-NIB-001 / SIM-NPWP-001','Hanggar Tangerang'],['PT Cakrawala Teknik Aviasi','SIM-NIB-002 / SIM-NPWP-002','Workshop Bekasi'],['PT Dirgantara Servis Mandiri','SIM-NIB-003 / SIM-NPWP-003','Hanggar Surabaya']]}else if(i===1){headers=['Fasilitas','Perusahaan','Kapasitas contoh'];rows=[['Hanggar Tangerang','PT Aero Nusantara','2 bay (simulasi)'],['Workshop Bekasi','PT Cakrawala Teknik Aviasi','120 pekerjaan/bulan (simulasi)']]}else if(i===2){headers=['Barang','Part number','Referensi HS simulasi'];rows=items.map(it=>[it.name,it.pn,it.hs])}else if(i===3){headers=['Kode','Jenis verifikasi','Kandidat hasil'];rows=Object.entries(types).map(([w,t])=>[w,t,outputs[w]])}else{headers=['Kategori','Konteks','Status'];rows=[['Persyaratan','Identitas & perizinan','Provisional'],['Bukti teknis','Pemeriksaan item','Provisional'],['Dokumentasi lapangan','Fasilitas / kondisi','Provisional'],['Hasil verifikasi','Draft hasil internal','Provisional']]};return head(names[i]||'Master','Referensi bersama untuk mengurangi input berulang. Seluruh entri fiktif.')+`<section class="panel"><div class="toolbar"><input placeholder="Cari referensi…" aria-label="Cari referensi" oninput="filterRows(this.value)">${btn('Usulkan koreksi',"openFeedback('Master / koreksi referensi')")}</div>${simpleTable(headers,rows)}</section><div class="note">Master menyimpan referensi bersama. Data transaksi pemeriksaan tetap berada pada Project. Referensi HS contoh tidak dapat dipakai untuk klasifikasi atau penetapan tarif.</div>`}
function simpleTable(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-search="${esc(r.join(' ').toLowerCase())}">${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><div id="no-results" class="empty hide">Tidak ada hasil yang cocok.</div></div>`}
function documentsPage(){let i=Number(route[1]||0),name=['SKVI & Perubahan','Laporan Pemeriksaan Realisasi','Register SKVBS','Laporan Operasional'][i];let list=db.projects.filter(p=>i===0?['W1','W2'].includes(p.w):i===1?p.w==='W3':i===2?p.w==='W4':true);return head(name,'Register lintas Project. Dokumen hasil dan pekerjaan verifikasi tetap memiliki status terpisah.')+`<div class="note">Tidak ada dokumen resmi yang diterbitkan pada prototype. Review internal bukan penerbitan, dan bukan Tanda Sah pemerintah.</div><section class="panel"><div class="toolbar"><input placeholder="Cari perusahaan atau jenis hasil…" aria-label="Cari dokumen hasil" oninput="filterRows(this.value)">${btn('Ekspor register simulasi',`exportRegister(${i})`)}</div><div class="tablewrap"><table><thead><tr><th>Jenis hasil / Project</th><th>Perusahaan</th><th>Status dokumen</th><th>Status resmi</th><th></th></tr></thead><tbody>${list.map(p=>`<tr data-search="${esc((p.name+' '+outputs[p.w]+' '+p.id).toLowerCase())}"><td><b>${outputs[p.w]}</b><small>${p.id}</small></td><td>${esc(p.name)}</td><td>${badge(p.result,'gray')}</td><td>${esc(p.official)}</td><td><a href="#project/${p.id}/result">Buka hasil</a></td></tr>`).join('')}</tbody></table><div id="no-results" class="empty hide">Tidak ada dokumen yang cocok.</div></div></section>`}function csv(rows){return '\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}function exportRegister(i){let list=db.projects.filter(p=>i===0?['W1','W2'].includes(p.w):i===1?p.w==='W3':i===2?p.w==='W4':true);download('Register-SIMULASI.csv',csv([['PROTOTYPE / BUKAN DOKUMEN RESMI'],['Project','Perusahaan','Jenis hasil','Status dokumen','Status resmi'],...list.map(p=>[p.id,p.name,outputs[p.w],p.result,p.official])]),'text/csv;charset=utf-8')}
function adminPage(){let i=Number(route[1]||0);let names=['Pengguna','Role & Hak Akses','Audit Aktivitas','Pengaturan Sistem'];let content=i===0?simpleTable(['Nama simulasi','Role hipotesis','Status'],[['Dimas Pratama','Verifikator','Demo'],['Rani Wibowo','Verifikator','Demo'],['Maya Anindita','Petugas Operasional','Demo'],['Bima Saputra','Penanggung Jawab Operasional','Demo'],['Admin Demo','System Administrator','Demo']]):i===1?simpleTable(['Role provisional','Tanggung jawab kandidat','Batasan'],roles.map((r,n)=>[r,['Registrasi dan pencatatan sumber','Pemeriksaan, bukti, temuan dan draft','Penugasan, monitoring dan koordinasi review','Akun, akses dan konfigurasi'][n],'Kewenangan final menunggu SOP'])):i===2?(db.activity.length?simpleTable(['Waktu WIB','Project','Aktivitas simulasi'],db.activity.map(a=>[a.time,a.project,a.text])):'<div class="empty">Belum ada aktivitas pengguna. Ubah penilaian atau jadwal untuk melihat jejak perubahan.</div>'):`<div class="keyvalues"><div><small>Versi prototype</small>${VERSION}</div><div><small>Integrasi SIINas</small>Ditunda · tidak ada koneksi</div><div><small>Penyimpanan</small>Lokal browser / perangkat</div><div><small>Autentikasi</small>Simulasi peran; tidak ada login sungguhan</div></div><div class="note warning">Reset mengembalikan data Project simulasi. Feedback dipertahankan agar catatan review tidak hilang.</div>${btn('Reset data simulasi','confirmReset()')}`;return head(names[i], 'Tampilan representatif untuk validasi struktur administrasi.')+`<div class="note">Pergantian peran di header hanya alat presentasi. Hak akses, pemisahan tugas dan kewenangan dokumen belum diterapkan atau disahkan.</div><section class="panel">${content}</section>`}function confirmReset(){dialog('Reset data simulasi?',`<p>Perubahan Project, jadwal, penilaian dan draft pada browser ini akan dikembalikan ke contoh awal. Feedback tetap disimpan.</p><div class="footeractions">${btn('Batal','closeModal()')}${btn('Reset data simulasi','resetDemo()','primary')}</div>`)}function resetDemo(){db=structuredClone(seed);save();closeModal();go('home');render();toast('Data simulasi dikembalikan. Feedback tetap tersimpan.')}
function publicPage(){return `<div class="public"><header class="publicnav"><a href="#public" class="brand"><i class="brandmark"></i><div>MRO<small>Aviation verification platform</small></div></a><nav class="publiclinks"><a href="#public" onclick="scrollSection(event,'layanan')">Layanan</a><a href="#public" onclick="scrollSection(event,'proses')">Proses</a><a href="#public" onclick="scrollSection(event,'faq')">FAQ</a><button class="dark" onclick="demoLogin()">Akses internal</button></nav></header><section class="hero"><div><p class="eyebrow">Konsep layanan verifikasi industri MRO</p><h1>Kejelasan pada setiap tahap verifikasi.</h1><p>Informasi verifikasi industri terkait barang dan bahan impor untuk kegiatan pemeliharaan, perbaikan, dan overhaul pesawat udara.</p><div class="actions">${btn('Kenali layanan',"document.getElementById('layanan').scrollIntoView({behavior:'smooth'})",'primary')}${btn('Informasi proses',"document.getElementById('proses').scrollIntoView({behavior:'smooth'})")}</div><p class="small" style="margin-top:22px">Website informasi · bukan portal permohonan</p></div><svg class="blueprint" viewBox="0 0 500 330" role="img" aria-label="Ilustrasi skematik pesawat dan titik pemeriksaan"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M 30 0 L 0 0 0 30" fill="none" stroke="#244d60" stroke-width="1"/></pattern></defs><rect width="500" height="330" fill="url(#grid)"/><g fill="none" stroke="currentColor" stroke-width="1.8"><ellipse cx="250" cy="165" rx="186" ry="126" opacity=".25" stroke-dasharray="4 6"/><path d="M250 35 Q266 45 266 83 L266 131 414 226 414 244 266 191 266 260 311 290 311 301 250 280 189 301 189 290 234 260 234 191 86 244 86 226 234 131 234 83 Q234 45 250 35Z" fill="#153c4e"/><path d="M250 42V279M141 222H360" opacity=".4" stroke-dasharray="4 5"/><circle cx="265" cy="137" r="6" fill="#3fc4e6"/><path d="M271 137H369L386 119"/><circle cx="236" cy="198" r="6" fill="#3fc4e6"/><path d="M230 198H115L98 179"/><circle cx="267" cy="259" r="6" fill="#3fc4e6"/><path d="M273 259H383"/></g><g fill="#9edff0" font-family="Segoe UI,Arial" font-size="12"><text x="362" y="108">Identitas & bukti</text><text x="25" y="169">Pemeriksaan</text><text x="365" y="280">Ketertelusuran</text></g></svg></section><section class="publicsection" id="layanan"><h2>Empat konteks, pemeriksaan yang terarah.</h2><p class="muted">Gambaran layanan konseptual. Lingkup penugasan dan kewenangan PT Surveyor Indonesia perlu dikonfirmasi.</p><div class="publiccards">${Object.entries(types).map(([w,t])=>`<article><span class="workflow">${w}</span><h3 style="margin-top:18px">${t}</h3><p>${{W1:'Penelaahan persyaratan, rencana kebutuhan impor dan kapasitas fasilitas.',W2:'Penelaahan perubahan yang mengacu pada data dan dokumen sebelumnya.',W3:'Pemeriksaan realisasi impor, penggunaan dan persediaan.',W4:'Penelaahan kategori, kondisi dan bukti barang atau bahan sisa.'}[w]}</p></article>`).join('')}</div></section><section class="publicsection" id="proses" style="background:var(--bg)"><h2>Informasi proses</h2><div class="twocol"><div><h3>Permohonan & referensi resmi</h3><p class="muted">Permohonan mengikuti kanal resmi yang berlaku. Website ini tidak menyediakan pendaftaran perusahaan atau pengajuan layanan.</p><h3>Penelaahan & hasil</h3><p class="muted">Pemeriksaan, bukti dan hasil mengikuti jenis verifikasi serta ketentuan dan kewenangan yang telah dikonfirmasi.</p></div><div class="panel"><h3>Referensi discovery</h3><p class="small muted">Referensi pada tahap discovery: Permenperin No. 16 Tahun 2026, PMK No. 50 Tahun 2026, serta PMK No. 26/PMK.010/2022 dan perubahannya. Ringkasan ini bukan nasihat hukum atau SOP.</p><p class="small">Katalog dan tautan referensi resmi perlu ditinjau sebelum website digunakan sebagai informasi layanan resmi.</p><span class="badge gray">Konten masih untuk validasi</span></div></div></section><section class="publicsection" id="faq"><h2>Pertanyaan umum</h2><details><summary>Apakah permohonan dapat diajukan dari website ini?</summary><p>Tidak. Website publik hanya menyajikan informasi. Pengajuan tetap mengikuti kanal resmi yang berlaku; prototype tidak terhubung ke SIINas.</p></details><details><summary>Apakah ini layanan sertifikasi kelaikudaraan?</summary><p>Konsep platform berfokus pada verifikasi industri terkait barang dan bahan MRO. Bukan sistem penerbitan sertifikat kelaikudaraan.</p></details><details><summary>Apakah hasil pada demo merupakan dokumen resmi?</summary><p>Tidak. Semua nama perusahaan, data pemeriksaan dan draft hasil adalah simulasi untuk memperoleh feedback.</p></details><details><summary>Bagaimana menghubungi tim layanan?</summary><p>Informasi unit, alamat, email dan nomor kontak layanan resmi belum diberikan client. Area kontak ini akan dilengkapi setelah konfirmasi; prototype tidak mengirim pesan.</p></details></section><footer class="publicfooter">Konsep untuk review PT Surveyor Indonesia · ${VERSION}<br>Penetapan, SOP, otorisasi dan isi layanan belum dikonfirmasi. Desain bukan requirement final.</footer></div>`}function scrollSection(e,id){e.preventDefault();document.getElementById(id).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}function demoLogin(){dialog('Akses internal · simulasi',`<p class="note">Tidak memerlukan kredensial. Pilih peran untuk mencoba navigasi internal dengan data fiktif.</p><label for="demorole">Peran demo</label><select id="demorole">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><p class="small muted">Ini bukan autentikasi. Kewenangan dan pemisahan tugas masih provisional.</p><div class="footeractions">${btn('Masuk demo',"role=document.getElementById('demorole').value;closeModal();go('home')",'primary')}</div>`)}
function context(){if(route[0]==='project')return `${project().id} / ${project().w} / ${route[2]||'summary'}${['verification','inspection'].includes(route[2])?' / Step '+(RV.ui.step+1):''}`;return location.hash.slice(1)||'home'}
function openFeedback(prefill=''){let ctx=context();dialog('Feedback untuk tim desain',`<form onsubmit="saveFeedback(event)"><p class="note">Halaman: <b>${esc(ctx)}</b><br>Catatan disimpan di browser ini. Tidak terkirim otomatis. Ekspor dan kirim file melalui kanal review yang disepakati.</p><div class="formgrid"><div><label for="fbname">Nama / inisial reviewer</label><input id="fbname" required value="${esc(getStored('mro-reviewer',''))}" placeholder="Contoh: Tim Operasional SI"></div><div><label for="fbcategory">Area feedback</label><select id="fbcategory"><option>Alur kerja</option><option>Navigasi & istilah</option><option>Data & dokumen</option><option>Tampilan & keterbacaan</option><option>Kewenangan / SOP</option></select></div><div><label for="fbpriority">Prioritas diskusi</label><select id="fbpriority"><option>Perlu diperbaiki</option><option>Menghambat pekerjaan</option><option>Saran peningkatan</option><option>Sudah sesuai untuk prototype</option></select></div><div><label for="fbtask">Tugas yang sedang dicoba</label><input id="fbtask" value="${esc(prefill)}" placeholder="Contoh: menilai perubahan W2"></div><div class="wide"><label for="fbnote">Apa yang sesuai atau membingungkan?</label><textarea id="fbnote" required placeholder="Jelaskan kondisi, ekspektasi dan bagian yang perlu dibahas…"></textarea></div><div class="wide"><label for="fbsuggestion">Usulan perbaikan (opsional)</label><textarea id="fbsuggestion" style="min-height:65px"></textarea></div></div><div class="footeractions">${btn('Lihat semua feedback',"closeModal();go('feedback')")}<button class="primary">Simpan feedback lokal</button></div></form>`);document.getElementById('modal').dataset.context=ctx;document.getElementById('modal').dataset.path=location.hash.slice(1)||'home'}
function saveFeedback(e){e.preventDefault();let v=n=>document.getElementById('fb'+n).value;feedback.push({id:'FB-'+Date.now(),version:VERSION,time:new Date().toISOString(),context:document.getElementById('modal').dataset.context,path:document.getElementById('modal').dataset.path,reviewer:v('name'),category:v('category'),priority:v('priority'),task:v('task'),note:v('note'),suggestion:v('suggestion'),decision:'Belum ditinjau'});try{localStorage.setItem('mro-siviki-feedback-v1',JSON.stringify(feedback));localStorage.setItem('mro-reviewer',JSON.stringify(v('name')))}catch{storageOK=false}closeModal();render();toast('Feedback dicatat '+(storageOK?'di browser ini':'di sesi ini')+'. Ekspor sebelum dibagikan ke tim desain.')}
function feedbackPage(){return head('Catatan feedback client',`${feedback.length} catatan lokal · tidak terkirim otomatis ke tim desain`,btn('Tambah feedback','openFeedback()','primary'))+`<div class="note warning">Penyimpanan terpisah pada setiap browser dan perangkat. Setelah review, klik Ekspor CSV atau JSON dan kirim file kepada fasilitator melalui kanal yang disepakati. Tidak ada pengumpulan terpusat.</div><div class="actions" style="margin-bottom:20px">${btn('Ekspor CSV','exportFeedback(false)')}${btn('Ekspor JSON','exportFeedback(true)')}${btn('Impor JSON reviewer','importFeedback()')}${btn('Salin ringkasan','copyFeedback()')}</div>${feedback.length?feedback.map((f,i)=>`<article class="panel"><div class="panelhead"><div>${badge(f.priority,f.priority==='Menghambat pekerjaan'?'red':'amber')} ${badge(f.category,'gray')}</div><span class="small muted">${esc(f.reviewer)}</span></div><a class="small" href="#${esc(f.path||'home')}">${esc(f.context)}</a><p style="margin:14px 0">${esc(f.note)}</p>${f.suggestion?`<div class="note"><b>Usulan:</b> ${esc(f.suggestion)}</div>`:''}<p class="small muted">Tugas: ${esc(f.task||'Tidak dicatat')} · ${esc(f.id)} · ${esc(f.version)}</p><div class="actions">${btn(f.decision||'Belum ditinjau',`reviewFeedback(${i})`,'textbutton')}${btn('Hapus catatan',`deleteFeedback(${i})`,'textbutton')}</div></article>`).join(''):'<section class="panel empty"><h2>Belum ada feedback</h2><p>Coba satu alur, lalu gunakan tombol Beri feedback di halaman yang sedang ditinjau.</p></section>'}`}
function exportFeedback(json){download('MRO-Feedback-Client-'+new Date().toISOString().slice(0,10)+(json?'.json':'.csv'),json?JSON.stringify({version:VERSION,notice:'Feedback prototype; bukan requirement final',feedback},null,2):csv([['ID','Versi','Waktu UTC','Halaman','Reviewer','Kategori','Prioritas','Tugas','Catatan','Usulan','Keputusan'],...feedback.map(f=>[f.id,f.version,f.time,f.context,f.reviewer,f.category,f.priority,f.task,f.note,f.suggestion,f.decision])]),json?'application/json':'text/csv;charset=utf-8')}
function importFeedback(){dialog('Gabungkan feedback reviewer',`<p class="note">Pilih JSON hasil ekspor prototype. Catatan dengan ID yang sudah ada tidak diduplikasi. Tidak mengunggah file ke server.</p><label for="importfile">File feedback JSON</label><input id="importfile" type="file" accept=".json,application/json" onchange="readFeedbackFile(this.files[0])"><p id="importstatus" role="status" class="small"></p>`)}async function readFeedbackFile(file){try{let data=JSON.parse(await file.text());if(!Array.isArray(data.feedback)||!data.feedback.every(f=>typeof f.id==='string'&&typeof f.note==='string'&&typeof f.context==='string'&&typeof f.reviewer==='string'&&typeof f.path==='string'&&/^[a-zA-Z0-9/_-]*$/.test(f.path)))throw Error('Format feedback tidak sesuai. Gunakan JSON ekspor prototype.');let count=0;for(let f of data.feedback){if(!feedback.some(a=>a.id===f.id)){feedback.push(f);count++}}try{localStorage.setItem('mro-siviki-feedback-v1',JSON.stringify(feedback))}catch{storageOK=false}closeModal();go('feedback');render();toast(count+' catatan digabungkan.')}catch(e){document.getElementById('importstatus').textContent='File tidak dapat dibaca: '+e.message}}
function feedbackText(){return 'MRO — Feedback client\n'+VERSION+'\nBukan requirement final\n\n'+feedback.map(f=>`${f.id} / ${f.context}\nReviewer: ${f.reviewer}\n${f.priority} / ${f.category}\nCatatan: ${f.note}\nUsulan: ${f.suggestion||'-'}\nKeputusan: ${f.decision}`).join('\n\n')}async function copyFeedback(){try{await navigator.clipboard.writeText(feedbackText());toast('Ringkasan feedback disalin.')}catch{dialog('Salin ringkasan secara manual',`<label for="copytext">Ringkasan</label><textarea id="copytext" style="min-height:280px">${esc(feedbackText())}</textarea>`)}}
function reviewFeedback(i){dialog('Hasil diskusi feedback',`<p>${esc(feedback[i].note)}</p><label for="decision">Keputusan sementara</label><select id="decision">${['Belum ditinjau','Perlu klarifikasi client','Diusulkan untuk revisi','Dipertahankan untuk prototype'].map(v=>`<option ${feedback[i].decision===v?'selected':''}>${v}</option>`).join('')}</select><p class="small muted">Keputusan ini tidak mengesahkan requirement atau SOP.</p><div class="footeractions">${btn('Simpan catatan diskusi',`saveDecision(${i})`,'primary')}</div>`)}function saveDecision(i){feedback[i].decision=document.getElementById('decision').value;try{localStorage.setItem('mro-siviki-feedback-v1',JSON.stringify(feedback))}catch{storageOK=false}closeModal();render()}function deleteFeedback(i){dialog('Hapus catatan feedback?',`<p>Catatan lokal ini akan dihapus. Ekspor terlebih dahulu jika perlu disimpan.</p><div class="footeractions">${btn('Batal','closeModal()')}${btn('Hapus catatan',`feedback.splice(${i},1);try{localStorage.setItem('mro-siviki-feedback-v1',JSON.stringify(feedback))}catch{}closeModal();render()` )}</div>`)}
function guide(){return head('Panduan review client','Gunakan prototype sebagai bahan diskusi, kemudian catat feedback pada halaman yang ditinjau.',btn('Catatan feedback',"go('feedback')",'primary'))+`<div class="twocol"><section class="panel"><h2>Sesi review sekitar 20–30 menit</h2>${[['Kenali dua pengalaman','Buka Website publik, jelajahi layanan dan FAQ, lalu masuk demo internal.','public'],['Coba registrasi dan penjadwalan','Buat Project melalui wizard; tetapkan verifikator dan tambahkan jadwal. Coba waktu yang bertabrakan.','schedule'],['Tinjau pemeriksaan W1–W4','Buka tab Verifikasi. Selesaikan step berurutan. Coba impor simulasi, matriks perubahan W2, selisih W3, dan kategori kondisi W4.','list/W1'],['Catat temuan dan susun hasil','Tambahkan temuan, catat tindak lanjut, simpan draft hasil dan coba review internal. Status resmi tetap terpisah.','project/MRO-DEMO-001/result'],['Kumpulkan hasil diskusi','Beri feedback pada setiap halaman, ekspor CSV/JSON dan kirim ke fasilitator. Gabungkan JSON dari reviewer lain.','feedback']].map(([t,d,path],i)=>`<div class="guideitem"><span class="num">${i+1}</span><div><b>${t}</b><p>${d}</p><a class="small" href="#${path}">Coba langkah ini</a></div></div>`).join('')}</section><div><section class="panel"><h2>Baseline Phase 1–4</h2><p class="small"><b>Phase 1:</b> arah produk disetujui bersyarat. Penetapan PT Surveyor Indonesia, SOP dan otorisasi masih perlu bukti.</p><p class="small"><b>Phase 2:</b> empat workflow terpisah, empat role sederhana, pencatatan manual; integrasi SIINas ditunda.</p><p class="small"><b>Phase 3:</b> Beranda berorientasi tugas; bukti dan tindakan berikutnya berada dalam konteks pekerjaan.</p><p class="small"><b>Phase 4:</b> registrasi terpisah dari jadwal; empat tab dan verifikasi berurutan sesuai konteks W1–W4. V0.12–V0.13 adalah kandidat desain, belum final.</p><div class="note">W1 → SKVI · W2 → SKVI Perubahan<br>W3 → Laporan Pemeriksaan<br>W4 → SKVBS jika berlaku</div></section><section class="panel"><h2>Kenapa rancangan berubah?</h2><p class="small">Registrasi dan jadwal dipisah agar Project tidak terhambat saat waktu kunjungan belum tersedia. Empat tab memisahkan Ringkasan, Verifikasi, Dokumen Penunjang, dan Dokumentasi. Surat Tugas, Berita Acara, temuan, dan penyusunan hasil dapat dibuka dari Ringkasan. Workspace W2, W3 dan W4 mengikuti objek pemeriksaan yang berbeda.</p><h3>Yang perlu jawaban client</h3><p class="small muted">Istilah menu, kecukupan data, urutan kegiatan, checklist resmi, satuan kapasitas, kategori W4, template hasil, pemisahan tugas, kewenangan review dan pemicu SLA.</p></section></div></div><section class="panel"><h2>Cara membagikan & menyimpan feedback</h2><p class="small">Untuk review tanpa akun hosting, bagikan berkas <b>PROTOTYPE-MRO-SIVIKI.html</b>. Buka dengan browser desktop; tidak perlu instalasi atau koneksi internet. Feedback tersimpan pada browser masing-masing. Ekspor JSON dari setiap reviewer dan impor pada halaman Catatan feedback untuk menggabungkannya; CSV siap dibaca di spreadsheet.</p><p class="small muted">Tidak ada backend, login sungguhan, API SIINas, pengiriman pesan, SOP definitif, penerbitan dokumen atau Tanda Sah. Perubahan simulasi bertahan di browser bila penyimpanan lokal tersedia. Gunakan reset untuk sesi demo baru; feedback dipertahankan.</p></section>`}
function render(){route=(location.hash.slice(1)||'home').split('/');let kind=route[0],content;document.title=(kind==='public'?'Informasi MRO':kind==='project'?project().name:kind==='feedback'?'Feedback Client':'MRO Verification')+' · Prototype';if(kind==='public'){document.getElementById('app').innerHTML=publicPage();return}content=kind==='home'?home():kind==='schedule'?schedule():kind==='register'?registerPage():kind==='list'?listPage():kind==='project'?detail():kind==='master'?masterPage():kind==='documents'?documentsPage():kind==='admin'?adminPage():kind==='feedback'?feedbackPage():guide();document.getElementById('app').innerHTML=shell(content);RV.afterRender()}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
